        [Str.HelpStartH] = "Primeiros passos",
        [Str.HelpStartBody] = "Abra Syncs → Adicionar um sync e informe serviço, ID e senha, ou leia o QR do navegador. Os favoritos são criptografados no dispositivo; o servidor não pode lê-los. Uma senha esquecida não pode ser recuperada.",
